/** One Coinbase tokenized stock (B20 asset) with its Chainlink total-return feed. */
export interface B20Token {
  readonly symbol: string;
  readonly name: string;
  readonly address: Address;
  readonly feed: Address;
  readonly decimals: 8;
  /** Aave V4 MAG7 spoke reserve id, when listed. */
  readonly aaveReserveId?: number;
  /** Aerodrome Slipstream USDC pool, when one with real liquidity exists. */
  readonly aerodromePool?: Address;
}

